void mainImage( out vec4 O, vec2 u )
{
    O = sqrt(T(u));
}

#define H(t) fract(sin((t)*vec4(127.1,311.7, 269.5,183.3)) *4e3 )

float line(vec2 p, vec2 a,vec2 b) {                          // --- draw lines
    p -= a, b -= a;
    return length(b) < .4                                   // to avoid artifacts at coords wrapping
             ? length(p - b * clamp(dot(p, b) / dot(b, b), 0., 1.) )
             : 9.;
}

void mainImage( out vec4 O, vec2 u )
{
    O = T(u);                                                // previous state/frame
    if (u.y<1.) {                                            // --- particles management
                     // state: (2i,0).xyzw: (pos,angle,dangle).  (2i+1,0).xy: prev value.
     // if ( O==O-O )
        if (iFrame<1 || iMouse.z>0. )                        // init particles
            O = vec4(R.x/R.y,1, 6.3,6.3) * H(u.x);
        int(u)%2 < 1 
          ? O.w  = mix( O.w,                                 // relaxation
                    textureLod(iChannel1,O.xy*R.y/R,0.).x    // image local density
                  - textureLod(iChannel1,u,99.).x, 
                  .1 ),                                      // update particle:
            O += .02* vec4( cos(O.z+vec2(0,11)),             //   location
                            50.*O.w, 0 )                     //   direction angle
                          // 80.*sin(iTime+O.w), 0 )
          : O = T(vec2(u.x-1.,0));                           // save prev pos (for segment drawing)
        O.xy = mod(O.xy, R/R.y);                             // domain wrapping
    } 
    else if ( iFrame > 1 )                                   // --- draw segments
        for( int i; i<int(R); i+=2 )
            O = max( O*.9995,                                // faded past
                     (1.-R.y* line( u/R.y, T(vec2(i+1,0)).xy, T(vec2(i,0)).xy )) // new segment
                     * max(0.,T(vec2(i,0)).w+.5)             // brighter where denser
                     * texture(iChannel1,u/R,0.)
                   );
}
